def get_shape(val: Any) ->Optional[List[int]]:
    if hasattr(val, 'type') and callable(val.type):
        try:
            return val.type().sizes()
        except Exception:
            return None
    return None


def einsum_flop_jit(inputs: List[Any], outputs: List[Any]) ->Number:
    equation = inputs[0].toIValue()
    input_shapes = [get_shape(v) for v in inputs[1].node().inputs()]

    letter_order = OrderedDict()
    for shape, term in zip(input_shapes, equation.split('->')[0].split(',')):
        for letter, dim in zip(term.strip(), shape):
            if letter not in letter_order:
                letter_order[letter] = dim

    flop = prod(list(letter_order.values()))
    return flop
